import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';


export type AIVoiceAgentProps = Record<string, any>;

const AIVoiceAgent: React.FC<AIVoiceAgentProps> = ({
  backgroundColor = "#050505",
  transparentBackground = true,
  durationInSeconds = 10,
  primaryColor = "#4F46E5",
  auraColor = "#818CF8",
  pulseSpeed = 1,
  symbolSize = 250,
  waveCount = 3,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Logic to prevent parser errors
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Spring animation for initial appearance
  const wakeUpScale = spring({
    frame,
    fps,
    config: { damping: 14, stiffness: 100 },
  });

  // Continuous breathing scale for the central orb
  const breathingScale = interpolate(
    Math.sin(frame * 0.05),
    [-1, 1],
    [0.97, 1.03]
  );

  const finalOrbScale = wakeUpScale * breathingScale;

  // Calculate loop duration based on pulse speed
  const loopFrames = Math.max(1, Math.floor(fps / pulseSpeed));

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        transition: "none",
      }}
    >
      {/* Aura Rings Layer */}
      <div
        style={{
          position: "absolute",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          transition: "none",
        }}
      >
        {Array.from({ length: waveCount }).map((_, i) => {
          const delay = (i * loopFrames) / waveCount;
          // Shift the frame so waves are staggered but loop smoothly
          const shiftedFrame = frame + (loopFrames - delay);
          const progress = (shiftedFrame % loopFrames) / loopFrames;

          // Expand outwards
          const scale = interpolate(progress, [0, 1], [1, 4]);
          
          // Fade in slightly, then fade out
          const opacity = interpolate(
            progress,
            [0, 0.1, 0.8, 1],
            [0, 0.4, 0, 0]
          ) * wakeUpScale; // Tie aura appearance to the initial wakeup

          return (
            <div
              key={`aura-${i}`}
              style={{
                position: "absolute",
                width: symbolSize,
                height: symbolSize,
                borderRadius: "50%",
                backgroundColor: auraColor,
                opacity: opacity,
                transform: `scale(${scale})`,
                filter: `blur(${symbolSize * 0.1}px)`,
                transition: "none",
              }}
            />
          );
        })}
      </div>

      {/* Central Agent Symbol (Orb) */}
      <div
        style={{
          position: "absolute",
          width: symbolSize,
          height: symbolSize,
          borderRadius: "50%",
          backgroundColor: primaryColor,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          gap: symbolSize * 0.08,
          boxShadow: `0 0 ${symbolSize * 0.5}px ${auraColor}`,
          transform: `scale(${finalOrbScale})`,
          transition: "none",
          overflow: "hidden",
        }}
      >
        {/* Inner Glow / Highlight */}
        <div
          style={{
            position: "absolute",
            top: "-20%",
            left: "-20%",
            width: "140%",
            height: "140%",
            background: "radial-gradient(circle at 30% 30%, rgba(255,255,255,0.4) 0%, rgba(255,255,255,0) 60%)",
            transition: "none",
          }}
        />

        {/* Voice Waveform Bars */}
        {Array.from({ length: 5 }).map((_, i) => {
          // Organic phase offset for each bar
          const phase = i * 0.8;
          const speed = 0.15 * pulseSpeed;
          
          // Animate the height of each bar using a sine wave
          const barScaleY = interpolate(
            Math.sin(frame * speed + phase),
            [-1, 1],
            [0.25, 0.85]
          );

          // Center bar is slightly thicker, outer bars are thinner
          const thicknessModifier = i === 2 ? 1 : i === 1 || i === 3 ? 0.8 : 0.6;

          return (
            <div
              key={`bar-${i}`}
              style={{
                zIndex: 1,
                width: symbolSize * 0.06 * thicknessModifier,
                height: "50%",
                backgroundColor: "#ffffff",
                borderRadius: symbolSize * 0.05,
                transform: `scaleY(${barScaleY})`,
                boxShadow: `0 0 ${symbolSize * 0.05}px rgba(255,255,255,0.8)`,
                transition: "none",
              }}
            />
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

export default AIVoiceAgent;